'use strict';
const assert = require('node:assert/strict');
const { createCache } = require('./src/cache');
const tick = () => new Promise(r => setImmediate(r));
function deferred() { let resolve, reject; const promise = new Promise((a, b) => { resolve = a; reject = b; }); return { promise, resolve, reject }; }

(async () => {
  // Rejection not cached; all waiters share reason; retry works.
  { let n = 0; const c = createCache({ now: () => 0, load() { n++; if (n === 1) throw 'boom'; return 'ok'; } });
    const [a, b] = [c.get('k'), c.get('k')];
    await assert.rejects(a, r => r === 'boom'); await assert.rejects(b, r => r === 'boom');
    assert.equal(await c.get('k'), 'ok'); assert.equal(n, 2); }

  // Obsolete flight must not detach the newer one or store.
  { const g1 = deferred(), g2 = deferred(); let n = 0;
    const c = createCache({ now: () => 0, load() { n++; return n === 1 ? g1.promise : g2.promise; } });
    const a = c.get('k'); await tick(); c.invalidate('k');
    const b = c.get('k'); await tick();
    g1.resolve('old'); assert.equal(await a, 'old');
    const b2 = c.get('k'); assert.equal(n, 2); // joins b
    g2.resolve('new'); assert.equal(await b, 'new'); assert.equal(await b2, 'new');
    assert.equal(await c.get('k'), 'new'); assert.equal(n, 2); }

  // Obsolete rejection must not detach newer flight.
  { const g1 = deferred(), g2 = deferred(); let n = 0;
    const c = createCache({ now: () => 0, load() { n++; return n === 1 ? g1.promise : g2.promise; } });
    const a = c.get('k'); await tick(); c.invalidate('k');
    const b = c.get('k'); await tick();
    g1.reject(new Error('x')); await assert.rejects(a);
    c.get('k'); assert.equal(n, 2);
    g2.resolve('v'); assert.equal(await b, 'v'); }

  // set wins over pending load; TTL not restarted by old load.
  { let t = 0; const g = deferred(); let n = 0;
    const c = createCache({ now: () => t, ttlMs: 10, load() { n++; return n === 1 ? g.promise : 'L' + n; } });
    const a = c.get('k'); await tick();
    c.set('k', 'S'); t = 5; g.resolve('old'); assert.equal(await a, 'old');
    assert.equal(await c.get('k'), 'S');
    t = 10; assert.equal(c.size, 0); assert.equal(await c.get('k'), 'L2'); }

  // clear detaches every flight.
  { const g = deferred(); let n = 0;
    const c = createCache({ now: () => 0, load(k) { n++; return n === 1 ? g.promise : 'fresh'; } });
    const a = c.get('k'); await tick(); c.clear(); g.resolve('stale');
    assert.equal(await a, 'stale'); assert.equal(c.size, 0); assert.equal(await c.get('k'), 'fresh'); }

  // TTL starts at commit; ttlMs=0 never reuses but dedups.
  { let t = 0; const g = deferred();
    const c = createCache({ now: () => t, ttlMs: 10, load: () => g.promise });
    const a = c.get('k'); await tick(); t = 8; g.resolve(1); await a;
    t = 17; assert.equal(c.size, 1); t = 18; assert.equal(c.size, 0); }
  { let n = 0; const c = createCache({ now: () => 0, ttlMs: 0, load: () => ++n });
    const p = [c.get('k'), c.get('k')]; assert.deepEqual(await Promise.all(p), [1, 1]);
    assert.equal(await c.get('k'), 2); }

  // load calls invalidate/set synchronously.
  { let n = 0; let c;
    c = createCache({ now: () => 0, load() { n++; if (n === 1) c.invalidate('k'); return 'v' + n; } });
    assert.equal(await c.get('k'), 'v1'); assert.equal(c.size, 0); assert.equal(await c.get('k'), 'v2'); }
  { let c; c = createCache({ now: () => 0, load() { c.set('k', 'S'); return 'L'; } });
    assert.equal(await c.get('k'), 'L'); assert.equal(await c.get('k'), 'S'); }

  // load reads own key without awaiting -> joins.
  { let n = 0, inner; let c;
    c = createCache({ now: () => 0, load(k) { n++; inner = c.get(k); return 'v'; } });
    assert.equal(await c.get('k'), 'v'); assert.equal(await inner, 'v'); assert.equal(n, 1); }

  console.log('smoke ok');
})().catch(e => { console.error(e); process.exit(1); });

